                continue
            todo = [(r, c)]
            visited[r][c] = True
            component = []
            while todo:
                y, x = todo.pop()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy = y + dy
                    xx = x + dx
                    if 0 <= yy < h and 0 <= xx < w:
                        if grid[yy][xx] != background and not visited[yy][xx]:
                            visited[yy][xx] = True
                            todo.append((yy, xx))
            components.append(component)

