    # which objects to erase, and the second gives the replacement color.
    replace_colors = set()
    fill = background
    for component in components:
        for y, x in component:
            if y + 1 < h and (y + 1, x) in component:
                replace_colors.add(grid[y][x])
            if x + 1 < w and (y, x + 1) in component:
                replace_colors.add(grid[y][x])
                fill = grid[y][x + 1]
    for component in components:
        if len(component) == 1:
            y, x = component[0]
            replace_colors.add(grid[y][x])

    shape_cells = []
    for component in components:
        if len(component) < 3:
            continue
        ys = [y for y, x in component]
        xs = [x for y, x in component]
        if max(ys) - min(ys) == 1 and max(xs) - min(xs) == 1:
            shape_cells.extend(component)

    if not shape_cells:
        return [row[:] for row in grid]
    top = min(y for y, x in shape_cells)
    bottom = max(y for y, x in shape_cells)
    left = min(x for y, x in shape_cells)
    right = max(x for y, x in shape_cells)

