                    mapping[source] = grid[y][xs[1]]
                    sequence.append(source)
                elif len(xs) == 1:
                    source = grid[y][xs[0]]
                    mapping[source] = grid[y][xs[0]]
                    sequence.append(source)
        else:
            ys = [y for y, x in comp]
            xs = [x for y, x in comp]
            if len(comp) in (3, 4) and max(ys) - min(ys) == 1 and max(xs) - min(xs) == 1:
                shapes.append(comp)

    groups = defaultdict(list)
    for comp in shapes:
        groups[grid[comp[0][0]][comp[0][1]]].extend(comp)
    for color in groups:
        if color not in sequence:
            sequence.append(color)

    result = [row[:] for row in grid]
    for color in sequence:
        cells = groups.get(color, [])
        if not cells:
            continue
        r0 = min(y for y, x in cells)
        r1 = max(y for y, x in cells)
        c0 = min(x for y, x in cells)
        c1 = max(x for y, x in cells)
        value = mapping.get(color, color)
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                result[r][c] = value

    # L-shaped objects mark the corners and remain on top.
    for comp in shapes:
        if len(comp) == 3:
            for r, c in comp:
                result[r][c] = grid[r][c]
    return result
